
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_tpssloc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_tpssloc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.716834207161210e-02, -4.693998723314720e-02, -4.660616376942073e-02, -4.611401409042268e-02, -4.537777528889080e-02, -4.424464938788248e-02, -4.238579004194099e-02, -3.883995211071537e-02, -3.026354621539223e-02, -1.301614406980074e-02, -4.462124593021155e-03, -3.990947667228401e-02, -4.848062045837890e-02, -3.269572302383495e-02, -1.182194798104955e-02, -9.709917688590275e-04, -1.008886967893914e-05, -4.922427482011584e-09, -9.191796714878479e-14, -1.503137904562804e-20]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


